//! Terms of use and privacy policy on the desktop (docs/legal/README.md): the version the
//! user must accept (bundled `legal.json`, generated by `tools/legal.py`), what was accepted
//! (`device.json`), the modal's copy, and the pages.
//!
//! Pure and tested on Linux. `gui.rs` shows the acceptance modal (the send window's legal
//! screen, `sendui`, or a native dialog when the webview is unavailable) before the tray
//! starts discovery/receiving and before `hoppyw send`; `main.rs` (`hoppy`) never blocks,
//! it only prints a notice once and `hoppy legal`.

use std::path::{Path, PathBuf};
use std::sync::OnceLock;
use std::time::SystemTime;

use serde::{Deserialize, Serialize};

/// Generated by `tools/legal.py` from docs/legal/ (never edited by hand).
pub const LEGAL_JSON: &str = include_str!("sendui/web/legal/legal.json");

/// The portal copies of the pages (`site/legal/`), for places that cannot show the
/// embedded ones (the CLI, the native fallback when writing them failed).
pub const PORTAL_LEGAL: &str = "https://marketto.github.io/hoppy/legal/";

/// The legal pages: `(file name, HTML)`, served by the send window under `/legal/` and
/// written to [`write_pages`]'s folder for the system browser.
pub const PAGES: [(&str, &str); 6] = [
    (
        "terms.it.html",
        include_str!("sendui/web/legal/terms.it.html"),
    ),
    (
        "terms.en.html",
        include_str!("sendui/web/legal/terms.en.html"),
    ),
    (
        "privacy.it.html",
        include_str!("sendui/web/legal/privacy.it.html"),
    ),
    (
        "privacy.en.html",
        include_str!("sendui/web/legal/privacy.en.html"),
    ),
    (
        "licenses.it.html",
        include_str!("sendui/web/legal/licenses.it.html"),
    ),
    (
        "licenses.en.html",
        include_str!("sendui/web/legal/licenses.en.html"),
    ),
];

/// `{"terms": N, "privacy": N}`: bumped in docs/legal/version.json when a text changes in
/// substance.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Version {
    pub terms: u32,
    pub privacy: u32,
}

/// What the user accepted, stored in device.json (`legal`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Acceptance {
    pub terms: u32,
    pub privacy: u32,
    /// UTC, `YYYY-MM-DD hh:mm:ss.mmmZ`.
    pub at: String,
}

impl Acceptance {
    /// Accepting `version` now.
    pub fn now(version: Version) -> Self {
        Self::at(version, SystemTime::now())
    }

    pub fn at(version: Version, t: SystemTime) -> Self {
        Acceptance {
            terms: version.terms,
            privacy: version.privacy,
            at: crate::diag::utc_stamp(t),
        }
    }
}

/// Why the modal is shown.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Need {
    /// Never accepted on this device: `title` + `body`.
    First,
    /// A newer terms or privacy version: `updated_title` + `updated_body`.
    Updated,
}

/// Whether `stored` covers `bundled`. A stored version higher than the bundled one (an older
/// app after a newer one) is fine: nothing to ask.
pub fn needed(stored: Option<&Acceptance>, bundled: Version) -> Option<Need> {
    match stored {
        None => Some(Need::First),
        Some(a) if a.terms < bundled.terms || a.privacy < bundled.privacy => Some(Need::Updated),
        Some(_) => None,
    }
}

/// The modal's copy in one language (docs/legal/strings.json).
#[derive(Debug, Clone, Deserialize)]
pub struct Strings {
    pub title: String,
    pub body: String,
    pub updated_title: String,
    pub updated_body: String,
    pub accept_terms: String,
    pub approve_clauses: String,
    pub read_privacy: String,
    #[serde(rename = "continue")]
    pub continue_: String,
    pub quit: String,
    pub legal: String,
    pub terms: String,
    pub privacy: String,
    pub licenses: String,
}

#[derive(Debug, Deserialize)]
struct Lang {
    it: Strings,
    en: Strings,
}

#[derive(Debug, Deserialize)]
struct Bundle {
    version: Version,
    strings: Lang,
}

fn bundle() -> &'static Bundle {
    static B: OnceLock<Bundle> = OnceLock::new();
    // Checked by the tests below: a broken legal.json never reaches a release.
    B.get_or_init(|| serde_json::from_str(LEGAL_JSON).expect("legal.json"))
}

/// The version this build asks the user to accept.
pub fn bundled() -> Version {
    bundle().version
}

pub fn strings(italian: bool) -> &'static Strings {
    let b = bundle();
    if italian {
        &b.strings.it
    } else {
        &b.strings.en
    }
}

/// One of the three documents.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Doc {
    Terms,
    Privacy,
    Licenses,
}

impl Doc {
    pub const ALL: [Doc; 3] = [Doc::Terms, Doc::Privacy, Doc::Licenses];

    /// `terms.it.html` and so on (the names in legal.json's `pages`).
    pub fn file(self, italian: bool) -> &'static str {
        match (self, italian) {
            (Doc::Terms, true) => "terms.it.html",
            (Doc::Terms, false) => "terms.en.html",
            (Doc::Privacy, true) => "privacy.it.html",
            (Doc::Privacy, false) => "privacy.en.html",
            (Doc::Licenses, true) => "licenses.it.html",
            (Doc::Licenses, false) => "licenses.en.html",
        }
    }

    pub fn label(self, s: &Strings) -> &str {
        match self {
            Doc::Terms => &s.terms,
            Doc::Privacy => &s.privacy,
            Doc::Licenses => &s.licenses,
        }
    }

    pub fn portal_url(self, italian: bool) -> String {
        format!("{PORTAL_LEGAL}{}", self.file(italian))
    }
}

/// The embedded page called `name` (`terms.it.html`, …).
pub fn page(name: &str) -> Option<&'static str> {
    PAGES
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, html)| *html)
}

/// Writes the six pages to `dir` (created; files overwritten) so the system browser can
/// open them offline; returns the path of `doc`. `dir` is per-user (`config::state_dir`),
/// never a shared temp folder.
pub fn write_pages(dir: &Path, doc: Doc, italian: bool) -> std::io::Result<PathBuf> {
    std::fs::create_dir_all(dir)?;
    for (name, html) in PAGES {
        std::fs::write(dir.join(name), html)?;
    }
    Ok(dir.join(doc.file(italian)))
}

/// The native fallback's text (no checkboxes there): the summary, then what the single
/// "I accept…" button declares, one line per checkbox of the window.
pub fn fallback_text(s: &Strings, need: Need, declares: &str) -> String {
    let body = match need {
        Need::First => s.body.as_str(),
        Need::Updated => s.updated_body.as_str(),
    };
    format!(
        "{body}\n\n{declares}\n• {}\n• {}\n• {}",
        s.accept_terms, s.approve_clauses, s.read_privacy
    )
}

pub fn title(s: &Strings, need: Need) -> &str {
    match need {
        Need::First => &s.title,
        Need::Updated => &s.updated_title,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::{Duration, UNIX_EPOCH};

    const V11: Version = Version {
        terms: 1,
        privacy: 1,
    };

    fn accepted(terms: u32, privacy: u32) -> Acceptance {
        Acceptance {
            terms,
            privacy,
            at: "2026-11-04 10:00:00.000Z".into(),
        }
    }

    #[test]
    fn asks_first_then_only_when_a_version_increases() {
        assert_eq!(needed(None, V11), Some(Need::First));
        assert_eq!(needed(Some(&accepted(1, 1)), V11), None);
        let v21 = Version {
            terms: 2,
            privacy: 1,
        };
        let v12 = Version {
            terms: 1,
            privacy: 2,
        };
        assert_eq!(needed(Some(&accepted(1, 1)), v21), Some(Need::Updated));
        assert_eq!(needed(Some(&accepted(1, 1)), v12), Some(Need::Updated));
        assert_eq!(needed(Some(&accepted(2, 1)), v12), Some(Need::Updated));
        // An older build after a newer one: already accepted something newer.
        assert_eq!(needed(Some(&accepted(3, 3)), V11), None);
        assert_eq!(needed(Some(&accepted(0, 0)), V11), Some(Need::Updated));
    }

    #[test]
    fn acceptance_records_the_version_and_utc_time() {
        let a = Acceptance::at(V11, UNIX_EPOCH + Duration::from_secs(1_793_793_600));
        assert_eq!((a.terms, a.privacy), (1, 1));
        assert_eq!(a.at, "2026-11-04 12:00:00.000Z");
        let json = serde_json::to_string(&a).unwrap();
        assert_eq!(
            json,
            r#"{"terms":1,"privacy":1,"at":"2026-11-04 12:00:00.000Z"}"#
        );
        assert_eq!(serde_json::from_str::<Acceptance>(&json).unwrap(), a);
    }

    #[test]
    fn bundle_matches_the_sources() {
        let source: Version =
            serde_json::from_str(include_str!("../../../docs/legal/version.json")).unwrap();
        assert_eq!(bundled(), source, "run python3 tools/legal.py");
        for italian in [true, false] {
            let s = strings(italian);
            for text in [
                &s.title,
                &s.body,
                &s.updated_title,
                &s.updated_body,
                &s.accept_terms,
                &s.approve_clauses,
                &s.read_privacy,
                &s.continue_,
                &s.quit,
                &s.legal,
                &s.terms,
                &s.privacy,
                &s.licenses,
            ] {
                assert!(!text.is_empty());
            }
            for doc in Doc::ALL {
                let html = page(doc.file(italian)).unwrap();
                assert!(html.starts_with("<!doctype html>"));
                assert!(!html.contains("<script"), "no scripts in the legal pages");
                assert!(doc.portal_url(italian).starts_with("https://"));
            }
        }
        assert_eq!(strings(true).quit, "Esci");
        assert_eq!(strings(false).quit, "Quit");
        // legal.json's page names are the ones served.
        let raw: serde_json::Value = serde_json::from_str(LEGAL_JSON).unwrap();
        for doc in ["terms", "privacy", "licenses"] {
            for lang in ["it", "en"] {
                let name = raw["pages"][doc][lang].as_str().unwrap();
                assert!(page(name).is_some(), "{name}");
            }
        }
        assert!(page("../legal.json").is_none() && page("legal.json").is_none());
    }

    #[test]
    fn pages_are_written_for_the_browser() {
        let dir = tempfile::tempdir().unwrap();
        let sub = dir.path().join("legal");
        let path = write_pages(&sub, Doc::Privacy, true).unwrap();
        assert_eq!(path, sub.join("privacy.it.html"));
        assert_eq!(std::fs::read_dir(&sub).unwrap().count(), 6);
        // Overwritten, not duplicated, the next time.
        write_pages(&sub, Doc::Terms, false).unwrap();
        assert_eq!(std::fs::read_dir(&sub).unwrap().count(), 6);
    }

    #[test]
    fn fallback_lists_what_the_button_declares() {
        let s = strings(true);
        let text = fallback_text(s, Need::First, "Accettando dichiari che:");
        assert!(text.starts_with(&s.body));
        assert!(text.contains(&format!("• {}", s.approve_clauses)));
        assert_eq!(text.matches('•').count(), 3);
        assert!(fallback_text(s, Need::Updated, "x").starts_with(&s.updated_body));
        assert_eq!(title(s, Need::Updated), s.updated_title);
    }
}
